+import { createEventCard } from './event-card.js';
+
+export function sortByStart(events, map = (event) => event) {
+  return events
+    .map((event, index) => ({ value: map(event), index, time: new Date(event.startsAt).getTime() }))
+    .sort((a, b) => a.time - b.time || a.index - b.index)
+    .map(({ value }) => value);
+}
+
+export function buildAgenda(events) {
+  return sortByStart(events, createEventCard);
+}

