+import { normalizeEmail } from '../lib/validation.js';
+import { uniqueBy } from '../lib/collections.js';
+
+export function buildRoster(signups) {
+  const entries = signups.map((signup) => ({
+    name: String(signup?.name ?? '').trim(),
+    email: normalizeEmail(signup?.email),
+  }));
+  return uniqueBy(entries, (entry) => entry.email)
+    .sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0));
+}

